import { useState, useRef, useCallback } from 'react';

// ─── Config ────────────────────────────────────────────────────────────────────
// Using proxy from package.json ("proxy": "http://localhost:5000")
// So /api/parse → http://localhost:5000/api/parse automatically
const API_BASE = '';

const EXAMPLES = [
  "Height is 30 cm, trunk is 2 cm, age is 2 months, leaf color is bright green, bark is smooth and soft, bark color is green, 22 leaves, curved",
  "Height is 50 cm, trunk is 3 cm, leaf color is light green, 10 leaves",
  "Height is 80 cm, trunk circumference 6 cm, age 5 months, yellowish green leaves, rough and peeling bark, medium brown, 9 leaves, very straight",
  "Shoot is 65 cm tall, trunk 4 cm, age 4 months, dark green leaves, slightly rough bark, light brown color, 14 leaves, slightly straight"
];

const FIELD_LABELS = {
  shoot_height_cm:        'Height (cm)',
  trunk_circumference_cm: 'Trunk Circ. (cm)',
  shoot_age_months:       'Age (months)',
  num_leaves:             'No. of Leaves',
  leaf_color:             'Leaf Colour',
  bark_texture:           'Bark Texture',
  bark_color:             'Bark Colour',
  straightness:           'Straightness',
};

const VERDICT = {
  'Ready':     { icon: '✅', cls: 'ready',      sub: 'Shoot is ready for harvest. Coppice at 6 cm from ground at 45°.' },
  'Borderline':{ icon: '⚠️', cls: 'borderline', sub: 'Shoot is close to ready. Check again in 2–3 weeks.' },
  'Not Ready': { icon: '❌', cls: 'not-ready',  sub: 'Shoot needs more time to mature.' },
};

// ─── Styles ───────────────────────────────────────────────────────────────────
const s = {
  page: { minHeight: '100vh', background: '#f4faf6', fontFamily: "'DM Sans','Segoe UI',system-ui,sans-serif" },

  header: { background: '#1a3a2a', color: '#fff', padding: '1.4rem 2rem', display: 'flex', alignItems: 'center', gap: 16 },
  leafIcon: { fontSize: '2rem' },
  headerTitle: { fontFamily: "'DM Serif Display', Georgia, serif", fontSize: '1.4rem', fontWeight: 400, lineHeight: 1.2 },
  headerSub: { fontSize: '0.78rem', opacity: 0.65, marginTop: 3, letterSpacing: '0.05em', textTransform: 'uppercase' },

  container: { maxWidth: 800, margin: '0 auto', padding: '2rem 1.2rem' },

  card: { background: '#fff', border: '1px solid #d0e8d8', borderRadius: 14, boxShadow: '0 2px 16px rgba(45,106,79,0.10)', padding: '1.5rem', marginBottom: '1.4rem' },

  cardTitle: { fontSize: '0.76rem', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.08em', color: '#2d6a4f', marginBottom: '1rem' },

  inputRow: { display: 'flex', gap: 10, alignItems: 'flex-start' },
  textarea: { flex: 1, border: '1.5px solid #d0e8d8', borderRadius: 10, padding: '0.75rem 1rem', fontSize: '1rem', lineHeight: 1.6, resize: 'vertical', minHeight: 95, color: '#1a1a1a', background: '#fafffe', outline: 'none', fontFamily: 'inherit', transition: 'border-color 0.2s' },

  micBtn: (active) => ({
    width: 52, height: 52, flexShrink: 0, borderRadius: '50%', border: 'none',
    background: active ? '#c0392b' : '#2d6a4f', color: '#fff', fontSize: '1.4rem',
    cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
    marginTop: 4, animation: active ? 'pulse 1s infinite' : 'none', transition: 'background 0.2s',
  }),

  voiceHint: { fontSize: '0.74rem', color: '#5a6672', marginTop: '0.5rem', display: 'flex', alignItems: 'center', gap: 5 },

  chipsWrap: { marginTop: '1rem' },
  chipsLabel: { fontSize: '0.76rem', color: '#5a6672', marginBottom: '0.5rem' },
  chipsRow: { display: 'flex', flexWrap: 'wrap', gap: 8 },
  chip: { fontSize: '0.76rem', background: '#d8f3dc', color: '#1a3a2a', border: '1px solid #d0e8d8', borderRadius: 20, padding: '4px 12px', cursor: 'pointer', userSelect: 'none', transition: 'background 0.15s' },

  parsedBox: { marginTop: '1rem', background: '#f0faf4', border: '1px solid #d0e8d8', borderRadius: 10, padding: '1rem', animation: 'slideIn 0.3s ease' },
  parsedTitle: { fontSize: '0.74rem', color: '#2d6a4f', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: '0.6rem' },
  parsedGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 8 },
  parsedPill: { background: '#fff', border: '1px solid #d0e8d8', borderRadius: 8, padding: '6px 10px' },
  parsedLabel: { color: '#5a6672', fontSize: '0.71rem', marginBottom: 2 },
  parsedVal: { fontWeight: 600, color: '#1a3a2a', fontSize: '0.82rem' },

  analyzeBtn: (disabled) => ({
    width: '100%', marginTop: '1rem', padding: '0.9rem',
    background: disabled ? '#a0c4b0' : '#2d6a4f', color: '#fff',
    border: 'none', borderRadius: 10, fontSize: '1rem', fontWeight: 600,
    cursor: disabled ? 'not-allowed' : 'pointer', fontFamily: 'inherit',
    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
    transition: 'background 0.2s',
  }),

  statusWrap: { textAlign: 'center', fontSize: '0.85rem', color: '#5a6672', padding: '0.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 },
  spinner: { display: 'inline-block', animation: 'spin 0.7s linear infinite', fontSize: '1.1rem' },
  errorMsg: { color: '#c0392b', background: '#fdecea', border: '1px solid #f1aaa5', borderRadius: 10, padding: '0.85rem 1rem', fontSize: '0.88rem', marginBottom: '1rem' },

  resultCard: { animation: 'slideIn 0.4s ease' },

  banner: (cls) => {
    const map = {
      'ready':      { bg: '#d8f3dc', border: '#52b788' },
      'borderline': { bg: '#fff8e1', border: '#e9a627' },
      'not-ready':  { bg: '#fdecea', border: '#c0392b' },
    };
    const m = map[cls] || map['not-ready'];
    return { background: m.bg, border: `1.5px solid ${m.border}`, borderRadius: 14, padding: '1.3rem 1.5rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: 16 };
  },
  bannerIcon: { fontSize: '2.8rem', flexShrink: 0 },
  bannerLabel: (cls) => {
    const colors = { ready: '#1a6e35', borderline: '#7a5200', 'not-ready': '#8b1a1a' };
    return { fontFamily: "'DM Serif Display',Georgia,serif", fontSize: '1.6rem', fontWeight: 400, color: colors[cls] || '#333' };
  },
  bannerSub: { fontSize: '0.86rem', color: '#5a6672', marginTop: 4 },

  confRow: { display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 },
  confLabel: { width: 100, fontSize: '0.82rem', color: '#5a6672' },
  confBarWrap: { flex: 1, height: 8, background: '#e8f5eb', borderRadius: 4, overflow: 'hidden' },
  confBar: (color, width) => ({ height: '100%', borderRadius: 4, background: color, width: `${width}%`, transition: 'width 0.7s ease' }),
  confPct: { width: 42, fontSize: '0.82rem', fontWeight: 600, textAlign: 'right' },

  reasonsTitle: { fontSize: '0.74rem', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.07em', color: '#2d6a4f', margin: '1rem 0 0.6rem' },
  reasonItem: { display: 'flex', gap: 10, alignItems: 'flex-start', padding: '8px 0', borderBottom: '1px solid #d0e8d8', fontSize: '0.87rem', lineHeight: 1.55 },
  reasonDot: { width: 8, height: 8, borderRadius: '50%', background: '#52b788', flexShrink: 0, marginTop: 6 },

  refSummary: { cursor: 'pointer', fontSize: '0.84rem', color: '#2d6a4f', fontWeight: 600, padding: '0.4rem 0', userSelect: 'none' },
  refTable: { width: '100%', borderCollapse: 'collapse', fontSize: '0.81rem', marginTop: '0.6rem' },
  th: { background: '#d8f3dc', padding: '6px 10px', textAlign: 'left', fontWeight: 600, color: '#1a3a2a' },
  td: { padding: '6px 10px', borderBottom: '1px solid #d0e8d8', color: '#1a1a1a' },
};

// ─── Component ────────────────────────────────────────────────────────────────
export default function CinnamonHarvest() {
  const [text, setText]           = useState('');
  const [loading, setLoading]     = useState(false);
  const [statusMsg, setStatusMsg] = useState('');
  const [error, setError]         = useState('');
  const [fields, setFields]       = useState(null);
  const [result, setResult]       = useState(null);
  const [recording, setRecording] = useState(false);
  const recRef    = useRef(null);
  const resultRef = useRef(null);

  // ── Voice input ─────────────────────────────────────────────────────────────
  const toggleVoice = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported. Please use Chrome or Edge.'); return; }

    if (recording) {
      recRef.current?.stop();
      setRecording(false);
      return;
    }

    const rec = new SR();
    rec.lang = 'en-US';
    rec.interimResults = true;
    rec.continuous = true;
    recRef.current = rec;

    const base = text;
    rec.onresult = (e) => {
      let interim = '', final = base;
      for (const r of e.results) {
        if (r.isFinal) final += (final ? ' ' : '') + r[0].transcript;
        else interim = r[0].transcript;
      }
      setText(final + (interim ? ' ' + interim : ''));
    };
    rec.onerror = () => setRecording(false);
    rec.onend   = () => setRecording(false);
    rec.start();
    setRecording(true);
  }, [recording, text]);

  // ── Analyze ──────────────────────────────────────────────────────────────────
  const analyze = useCallback(async () => {
    if (!text.trim()) { alert('Please type or speak your shoot measurements first.'); return; }

    setLoading(true);
    setError('');
    setResult(null);
    setFields(null);

    try {
      // Step 1: Parse text → structured fields
      setStatusMsg('Understanding your description...');
      const parseRes = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!parseRes.ok) throw new Error(`Parse failed (${parseRes.status}): ${await parseRes.text()}`);
      const parseData = await parseRes.json();
      const parsedFields = parseData.fields ?? parseData;
      setFields(parsedFields);

      // Step 2: Predict readiness
      setStatusMsg('Running harvest readiness model...');
      const predRes = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: parsedFields }),
      });
      if (!predRes.ok) throw new Error(`Predict failed (${predRes.status}): ${await predRes.text()}`);
      const predData = await predRes.json();

      setResult(predData);
      setStatusMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 80);

    } catch (err) {
      setError(err.message);
      setStatusMsg('');
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [text]);

  const handleKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); analyze(); }
  };

  const v = result ? (VERDICT[result.prediction] || VERDICT['Not Ready']) : null;

  return (
    <div style={s.page}>

      {/* ── Header ── */}
      <header style={s.header}>
        <div style={s.leafIcon}>🌿</div>
        <div>
          <div style={s.headerTitle}>Ceylon Cinnamon Harvest Readiness</div>
          <div style={s.headerSub}>GI Certified · CCGI Guideline Based · ML Powered</div>
        </div>
      </header>

      <div style={s.container}>

        {/* ── Input Card ── */}
        <div style={s.card}>
          <div style={s.cardTitle}>🎤 Describe your cinnamon shoot</div>

          <div style={s.inputRow}>
            <textarea
              style={s.textarea}
              value={text}
              onChange={e => setText(e.target.value)}
              onKeyDown={handleKey}
              placeholder={`Type or speak naturally, e.g.:\nHeight is 75 cm, trunk is 5 cm, age is 5 months, leaf color is yellowish green, bark is rough and peeling, bark color is medium brown, 8 leaves, very straight`}
            />
            <button style={s.micBtn(recording)} onClick={toggleVoice} title="Click to speak">
              {recording ? '⏹' : '🎤'}
            </button>
          </div>

          <div style={s.voiceHint}>
            <span>🎤</span> Click the mic and speak your measurements, or type above. Press Enter to analyze.
          </div>

          {/* Example chips */}
          <div style={s.chipsWrap}>
            <div style={s.chipsLabel}>Try an example:</div>
            <div style={s.chipsRow}>
              {['Young shoot (Not Ready)', '50 cm, light green', 'Mature shoot (Ready)', 'Borderline case'].map((label, i) => (
                <span key={i} style={s.chip} onClick={() => { setText(EXAMPLES[i]); setResult(null); setFields(null); setError(''); }}>
                  {label}
                </span>
              ))}
            </div>
          </div>

          {/* Parsed fields preview */}
          {fields && (
            <div style={s.parsedBox}>
              <div style={s.parsedTitle}>📋 Understood values</div>
              <div style={s.parsedGrid}>
                {Object.entries(fields).filter(([, v]) => v !== null && v !== undefined).map(([k, val]) => (
                  <div key={k} style={s.parsedPill}>
                    <div style={s.parsedLabel}>{FIELD_LABELS[k] || k}</div>
                    <div style={s.parsedVal}>{String(val)}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <button style={s.analyzeBtn(loading)} disabled={loading} onClick={analyze}>
            {loading ? '⏳ Analyzing...' : '🔍 Check Harvest Readiness'}
          </button>
        </div>

        {/* ── Status ── */}
        {loading && statusMsg && (
          <div style={s.statusWrap}>
            <span style={s.spinner}>⟳</span>
            {statusMsg}
          </div>
        )}

        {/* ── Error ── */}
        {error && (
          <div style={s.errorMsg}>
            ⚠️ <strong>Error:</strong> {error}
            <br /><small>Make sure your Flask backend is running at localhost:5000</small>
          </div>
        )}

        {/* ── Result Card ── */}
        {result && (
          <div style={{ ...s.card, ...s.resultCard }} ref={resultRef}>

            {/* Banner */}
            <div style={s.banner(v.cls)}>
              <div style={s.bannerIcon}>{v.icon}</div>
              <div>
                <div style={s.bannerLabel(v.cls)}>{result.prediction}</div>
                <div style={s.bannerSub}>{v.sub}</div>
              </div>
            </div>

            {/* Confidence bars */}
            {[
              { label: 'Ready',      key: 'Ready',      color: '#52b788' },
              { label: 'Borderline', key: 'Borderline', color: '#e9a627' },
              { label: 'Not Ready',  key: 'Not Ready',  color: '#c0392b' },
            ].map(({ label, key, color }) => (
              <div key={key} style={s.confRow}>
                <div style={s.confLabel}>{label}</div>
                <div style={s.confBarWrap}>
                  <div style={s.confBar(color, result.confidence?.[key] ?? 0)} />
                </div>
                <div style={s.confPct}>{Math.round(result.confidence?.[key] ?? 0)}%</div>
              </div>
            ))}

            {/* Reasons */}
            <div style={s.reasonsTitle}>Why this result?</div>
            {result.reasons?.map((r, i) => (
              <div key={i} style={{ ...s.reasonItem, borderBottom: i === result.reasons.length - 1 ? 'none' : '1px solid #d0e8d8' }}>
                <div style={s.reasonDot} />
                <div>{r}</div>
              </div>
            ))}
          </div>
        )}

        {/* ── Reference Guide ── */}
        <div style={s.card}>
          <details>
            <summary style={s.refSummary}>📖 CCGI Harvest Reference Guide</summary>
            <table style={s.refTable}>
              <thead>
                <tr>
                  <th style={s.th}>Feature</th>
                  <th style={s.th}>Ideal for Harvest</th>
                  <th style={s.th}>Not Ready</th>
                </tr>
              </thead>
              <tbody>
                {[
                  ['Shoot Height',       '60–100 cm',        'Below 45 cm'],
                  ['Trunk Circumference','4–8 cm',            'Below 3 cm'],
                  ['Shoot Age',          '4.5–5.5 months',   'Below 3 months'],
                  ['Leaf Colour',        'Yellowish green',   'Bright / dark green'],
                  ['Bark Texture',       'Rough and peeling', 'Smooth and soft'],
                  ['Bark Colour',        'Medium brown',      'Green / light brown'],
                  ['Straightness',       'Very straight',     'Curved'],
                  ['Number of Leaves',   '6–12',              'Over 20'],
                ].map(([f, g, b]) => (
                  <tr key={f}>
                    <td style={s.td}>{f}</td>
                    <td style={{ ...s.td, color: '#1a6e35', fontWeight: 500 }}>{g}</td>
                    <td style={{ ...s.td, color: '#8b1a1a' }}>{b}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </details>
        </div>

      </div>
    </div>
  );
}
